#include <Adafruit_NeoPixel.h>
Adafruit_NeoPixel ring(12, 18, NEO_GRB + NEO_KHZ800);
void setup() {
  ring.begin();
  ring.setBrightness(80);
  for (int i = 0; i < 12; i++) {
    ring.setPixelColor(i, ring.Color(0, 160, 40));
  }
  ring.show();
}
void loop() {}
